shell_commands:
/bin/zsh -lc "cat > src/types/sessionListFrames.test.ts <<'EOF'
import type {IncomingMessage, ListSessionsMessage, OutgoingMessage, SessionListMessage, SessionSummaryFrame} from '../index.js';

// specs/hal-engine-conversation-list/spec.md#1
it('exposes typed session list frames with wire-format dates', () => {
  const request: ListSessionsMessage = {type: 'list_sessions', limit: 2, before: {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'}};
  const row: SessionSummaryFrame = {sessionId: 's1', createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-01T00:00:00.000Z', entryCount: 1};
  const response: SessionListMessage = {type: 'session_list', sessions: [row]};
  const incoming: IncomingMessage = request;
  const outgoing: OutgoingMessage = response;

  expect(JSON.parse(JSON.stringify({incoming, outgoing}))).toEqual({incoming: request, outgoing: response});
});
EOF
NODE_OPTIONS=--experimental-vm-modules timeout 300 npx jest --runInBand --runTestsByPath src/types/sessionListFrames.test.ts"

/bin/zsh -lc "rm src/types/sessionListFrames.test.ts
cat > src/transport/ws/listSessionsValidation.test.ts <<'EOF'
import {validateMessage} from './validation.js';

// specs/hal-engine-conversation-list/spec.md#1
it('validates list_sessions pagination and strips unknown fields', () => {
  expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
  expect(validateMessage({type: 'list_sessions', limit: 0, before: {sessionId: 's', updatedAt: 0}, userId: 'other'})).toEqual({
    valid: true, data: {type: 'list_sessions', limit: 0, before: {sessionId: 's', updatedAt: 0}},
  });
  for (const limit of [-1, 1.5, '1']) {
    expect(validateMessage({type: 'list_sessions', limit}).valid).toBe(false);
  }
  for (const before of [null, {}, {sessionId: '', updatedAt: 0}, {sessionId: 'x'.repeat(129), updatedAt: 0}, {sessionId: 's', updatedAt: 'invalid'}, {sessionId: 's', updatedAt: Infinity}]) {
    expect(validateMessage({type: 'list_sessions', before}).valid).toBe(false);
  }
});
EOF
NODE_OPTIONS=--experimental-vm-modules timeout 300 npx jest --runInBand --runTestsByPath src/transport/ws/listSessionsValidation.test.ts"
